package com.expandedbanktagsviewer;

import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Point;
import net.runelite.api.ScriptEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.banktags.tabs.TabSprites;

/** Owns the chest toggle and the hidden Bank Tags new-tab button for one bank session. */
@Singleton
final class ToggleWidgetController
{
	static final String TOGGLE_OPTION = "Toggle expanded bank tabs";
	static final String NEW_TAB_OPTION = "New tag tab";

	private static final int TOGGLE_OP = 1;
	private static final int NEW_TAB_OP = 2;

	private final Client client;
	private final ClientThread clientThread;
	private Widget originalNewTab;
	private Widget layerParent;
	private Widget layer;
	private Widget background;
	private Widget icon;
	private Widget hitbox;
	private boolean originalHidden;
	private boolean originalStateCaptured;
	private boolean expanded;
	private boolean enabled;
	private boolean mouseDown;
	private int lastToggleTick = -1;
	private int lastNewTabTick = -1;
	private Listener listener;

	@Inject
	ToggleWidgetController(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	void maintain(Widget bankContent, boolean enabled, boolean expanded, Listener listener)
	{
		this.enabled = enabled;
		this.expanded = expanded;
		this.listener = listener;
		if (bankContent == null)
		{
			return;
		}

		Widget liveNewTab = getLiveNewTabWidget(bankContent);
		if (liveNewTab == null)
		{
			// Bank Tags briefly removes its tab children while rebuilding them.
			// Keep our layer attached so the next client tick reuses it instead of
			// appending another hidden dynamic child to the bank interface.
			hideOverlay();
			return;
		}
		if (originalNewTab != liveNewTab)
		{
			restoreOriginal();
			originalNewTab = liveNewTab;
			originalHidden = originalNewTab.isHidden();
			originalStateCaptured = true;
		}

		setHidden(originalNewTab, enabled || originalHidden);
		if (!enabled)
		{
			hideOverlay();
			return;
		}

		Widget newLayerParent = findLayerParent(bankContent);
		if (newLayerParent == null)
		{
			hideOverlay();
			return;
		}
		if (layerParent != newLayerParent)
		{
			removeOverlay();
			layerParent = newLayerParent;
		}

		ensureOverlay();
		position();
		update();
	}

	void pollFallbackClick()
	{
		boolean currentMouseDown = client.getMouseCurrentButton() == 1;
		Point mouse = client.getMouseCanvasPosition();
		Rectangle bounds = hitbox == null ? null : hitbox.getBounds();
		if (currentMouseDown && !mouseDown && mouse != null && bounds != null
			&& bounds.contains(mouse.getX(), mouse.getY()))
		{
			handleToggleClick();
		}
		mouseDown = currentMouseDown;
	}

	boolean owns(Widget widget)
	{
		return widget != null && (widget == layer || widget == background || widget == icon || widget == hitbox);
	}

	boolean handleMenuOption(String option)
	{
		if (TOGGLE_OPTION.equals(option))
		{
			clientThread.invokeLater(this::handleToggleClick);
			return true;
		}
		if (NEW_TAB_OPTION.equals(option))
		{
			clientThread.invokeLater(this::handleNewTabClick);
			return true;
		}
		return false;
	}

	Widget getLayerParent()
	{
		return layerParent;
	}

	void updateState(boolean enabled, boolean expanded)
	{
		this.enabled = enabled;
		this.expanded = expanded;
		if (originalNewTab != null && originalStateCaptured)
		{
			setHidden(originalNewTab, enabled || originalHidden);
		}
		update();
	}

	void dispose()
	{
		restoreOriginal();
		removeOverlay();
		listener = null;
		mouseDown = false;
	}

	private void ensureOverlay()
	{
		if (layerParent == null || originalNewTab == null)
		{
			return;
		}
		// Dynamic widget layers are not reliably reported through getChildren().
		// Treat this controller's references as authoritative for the lifetime of
		// the bank interface. WidgetClosed resets them when that lifetime ends.
		// Checking getChildren() here caused a new layer and five new callbacks to
		// be appended on every ClientTick even though the existing layer was live.
		if (layer != null && background != null && icon != null && hitbox != null)
		{
			return;
		}

		Widget stableParent = layerParent;
		removeOverlay();
		layerParent = stableParent;
		layer = layerParent.createChild(-1, WidgetType.LAYER);
		layer.setOriginalWidth(ExpandedViewLayout.TAB_WIDTH);
		layer.setOriginalHeight(ExpandedViewLayout.TAB_HEIGHT);
		layer.setNoClickThrough(true);

		background = layer.createChild(-1, WidgetType.GRAPHIC);
		background.setOriginalWidth(ExpandedViewLayout.TAB_WIDTH);
		background.setOriginalHeight(ExpandedViewLayout.TAB_HEIGHT);
		background.setSpriteId(TabSprites.TAB_BACKGROUND.getSpriteId());
		background.setItemId(-1);
		background.setItemQuantity(-1);
		background.setBorderType(0);
		background.setName("");
		background.setHasListener(true);
		background.setNoClickThrough(false);
		background.setOnMouseOverListener((JavaScriptCallback) event -> setActiveSprite());
		background.setOnMouseLeaveListener((JavaScriptCallback) event -> update());

		icon = layer.createChild(-1, WidgetType.GRAPHIC);
		icon.setOriginalX(3);
		icon.setOriginalY(4);
		icon.setOriginalWidth(Constants.ITEM_SPRITE_WIDTH);
		icon.setOriginalHeight(Constants.ITEM_SPRITE_HEIGHT);
		icon.setSpriteId(-1);
		icon.setItemId(ItemID.BCS_CHEST);
		icon.setItemQuantity(-1);
		icon.setBorderType(1);
		icon.setClickMask(0);
		icon.setName("");
		icon.setNoClickThrough(false);
		icon.revalidate();

		hitbox = layer.createChild(-1, WidgetType.GRAPHIC);
		hitbox.setOriginalWidth(ExpandedViewLayout.TAB_WIDTH);
		hitbox.setOriginalHeight(ExpandedViewLayout.TAB_HEIGHT);
		hitbox.setSpriteId(-1);
		hitbox.setItemId(-1);
		hitbox.setItemQuantity(-1);
		hitbox.setName("");
		hitbox.setAction(TOGGLE_OP, TOGGLE_OPTION);
		hitbox.setAction(NEW_TAB_OP, NEW_TAB_OPTION);
		hitbox.setHasListener(true);
		hitbox.setNoClickThrough(true);
		hitbox.setOnOpListener((JavaScriptCallback) this::handleOperation);
		hitbox.setOnMouseOverListener((JavaScriptCallback) event -> setActiveSprite());
		hitbox.setOnMouseLeaveListener((JavaScriptCallback) event -> update());
		hitbox.revalidate();
		layer.revalidate();
	}

	private void update()
	{
		if (layer == null || background == null || icon == null || hitbox == null)
		{
			return;
		}
		boolean hidden = !enabled;
		setHidden(layer, hidden);
		setHidden(background, hidden);
		setHidden(icon, hidden);
		setHidden(hitbox, hidden);
		int spriteId = expanded
			? TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId() : TabSprites.TAB_BACKGROUND.getSpriteId();
		if (background.getSpriteId() != spriteId)
		{
			background.setSpriteId(spriteId);
			background.revalidate();
		}
	}

	private void setActiveSprite()
	{
		if (background != null)
		{
			background.setSpriteId(TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId());
			background.revalidate();
		}
	}

	private void position()
	{
		if (layer == null || layerParent == null || originalNewTab == null)
		{
			return;
		}
		Point relative = WidgetGeometry.relativeLocation(originalNewTab, layerParent);
		if (relative != null)
		{
			position(relative.getX(), relative.getY());
		}
		else
		{
			Point buttonLocation = originalNewTab.getCanvasLocation();
			Point parentLocation = layerParent.getCanvasLocation();
			if (buttonLocation == null || parentLocation == null)
			{
				return;
			}
			position(buttonLocation.getX() - parentLocation.getX(),
				buttonLocation.getY() - parentLocation.getY());
		}
	}

	private void position(int x, int y)
	{
		if (layer.getOriginalX() == x && layer.getOriginalY() == y
			&& layer.getOriginalWidth() == ExpandedViewLayout.TAB_WIDTH
			&& layer.getOriginalHeight() == ExpandedViewLayout.TAB_HEIGHT)
		{
			return;
		}
		layer.setOriginalX(x);
		layer.setOriginalY(y);
		layer.setOriginalWidth(ExpandedViewLayout.TAB_WIDTH);
		layer.setOriginalHeight(ExpandedViewLayout.TAB_HEIGHT);
		layer.revalidate();
	}

	private static void setHidden(Widget widget, boolean hidden)
	{
		if (widget.isHidden() != hidden)
		{
			widget.setHidden(hidden);
			widget.revalidate();
		}
	}

	private Widget getLiveNewTabWidget(Widget bankContent)
	{
		Widget[] children = bankContent.getChildren();
		return children == null || children.length <= 3 ? null : children[3];
	}

	private Widget findLayerParent(Widget bankContent)
	{
		Widget found = WidgetGeometry.findLayerAncestor(client.getWidget(InterfaceID.Bankmain.UNIVERSE));
		if (found != null && found != bankContent)
		{
			return found;
		}
		return WidgetGeometry.findLayerAncestor(bankContent.getParent());
	}

	private void restoreOriginal()
	{
		if (originalNewTab != null && originalStateCaptured)
		{
			setHidden(originalNewTab, originalHidden);
		}
		originalNewTab = null;
		originalStateCaptured = false;
	}

	private void removeOverlay()
	{
		hideOverlay();
		layer = null;
		background = null;
		icon = null;
		hitbox = null;
		layerParent = null;
	}

	private void hideOverlay()
	{
		if (layer != null)
		{
			setHidden(layer, true);
		}
	}

	private void handleOperation(ScriptEvent event)
	{
		switch (event.getOp() - 1)
		{
			case TOGGLE_OP:
				handleToggleClick();
				break;
			case NEW_TAB_OP:
				handleNewTabClick();
				break;
			default:
				break;
		}
	}

	private void handleToggleClick()
	{
		int tick = client.getTickCount();
		if (lastToggleTick != tick && listener != null)
		{
			lastToggleTick = tick;
			listener.toggleExpandedView();
		}
	}

	private void handleNewTabClick()
	{
		int tick = client.getTickCount();
		if (lastNewTabTick != tick && listener != null)
		{
			lastNewTabTick = tick;
			listener.createBankTab();
		}
	}

	interface Listener
	{
		void toggleExpandedView();
		void createBankTab();
	}
}

package com.expandedbanktagsviewer;

import java.awt.Rectangle;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.WidgetType;

/** Owns the invisible drag/scroll input surface over the bank scrollbar. */
@Singleton
final class ExpandedScrollbarController
{
	private final Client client;
	private Widget input;
	private Listener listener;

	@Inject
	ExpandedScrollbarController(Client client)
	{
		this.client = client;
	}

	void maintain(Widget layerParent, boolean visible, Listener listener)
	{
		this.listener = listener;
		if (!visible || layerParent == null)
		{
			hide();
			return;
		}

		Widget bankScrollbar = client.getWidget(InterfaceID.Bankmain.SCROLLBAR);
		if (bankScrollbar == null)
		{
			hide();
			return;
		}

		Widget[] children = layerParent.getChildren();
		boolean attached = input != null && children != null
			&& Arrays.stream(children).anyMatch(child -> child == input);
		if (!attached)
		{
			dispose();
			this.listener = listener;
			input = layerParent.createChild(-1, WidgetType.RECTANGLE);
			input.setFilled(false);
			input.setOpacity(0);
			input.setHasListener(true);
			input.setNoClickThrough(true);
			input.setNoScrollThrough(true);
			input.setClickMask(WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
			input.setDragDeadTime(1);
			input.setDragDeadZone(1);
			input.setOnScrollWheelListener((JavaScriptCallback) event ->
			{
				if (this.listener != null)
				{
					this.listener.scrollBy(event.getMouseY());
				}
			});
		}

		Point relative = WidgetGeometry.relativeLocation(bankScrollbar, layerParent);
		if (relative != null)
		{
		position(relative.getX(), relative.getY(), bankScrollbar.getWidth(), bankScrollbar.getHeight());
		}
		else
		{
			Point scrollbarLocation = bankScrollbar.getCanvasLocation();
			Point parentLocation = layerParent.getCanvasLocation();
			if (scrollbarLocation == null || parentLocation == null)
			{
				return;
			}
			position(scrollbarLocation.getX() - parentLocation.getX(),
				scrollbarLocation.getY() - parentLocation.getY(),
				bankScrollbar.getWidth(), bankScrollbar.getHeight());
		}
	}

	private void position(int x, int y, int width, int height)
	{
		width = Math.max(1, width);
		height = Math.max(1, height);
		if (input.getOriginalX() == x && input.getOriginalY() == y
			&& input.getOriginalWidth() == width && input.getOriginalHeight() == height
			&& !input.isHidden())
		{
			return;
		}
		input.setOriginalX(x);
		input.setOriginalY(y);
		input.setOriginalWidth(width);
		input.setOriginalHeight(height);
		input.setHidden(false);
		input.revalidate();
	}

	boolean handleDrag(Widget dragged)
	{
		if (input == null || dragged != input)
		{
			return false;
		}
		updateFromMouse();
		return true;
	}

	void pollDrag()
	{
		updateFromMouse();
	}

	void hide()
	{
		if (input != null)
		{
			if (!input.isHidden())
			{
				input.setHidden(true);
				input.revalidate();
			}
		}
	}

	void dispose()
	{
		hide();
		input = null;
		listener = null;
	}

	private void updateFromMouse()
	{
		if (input == null || listener == null || client.getMouseCurrentButton() != 1)
		{
			return;
		}
		Rectangle bounds = input.getBounds();
		Point mouse = client.getMouseCanvasPosition();
		if (bounds == null || mouse == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		int maxScroll = listener.getMaxScroll();
		if (maxScroll == 0)
		{
			return;
		}
		int padding = Math.min(16, Math.max(1, bounds.height / 4));
		int trackTop = bounds.y + padding;
		int trackLength = Math.max(1, bounds.y + bounds.height - padding - trackTop);
		int position = Math.max(0, Math.min(trackLength, mouse.getY() - trackTop));
		listener.setScrollOffset(Math.round((float) position / trackLength * maxScroll));
	}

	interface Listener
	{
		void scrollBy(int direction);
		int getMaxScroll();
		void setScrollOffset(int offset);
	}
}

package com.expandedbanktagsviewer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable group data consumed by the expanded-view renderer. */
final class ExpandedViewGroup
{
	private final String name;
	private final String id;
	private final List<BankTab> tabs;
	private final boolean collapsed;

	ExpandedViewGroup(String name, String id, List<BankTab> tabs, boolean collapsed)
	{
		this.name = name;
		this.id = id;
		this.tabs = Collections.unmodifiableList(new ArrayList<>(tabs));
		this.collapsed = collapsed;
	}

	String getName()
	{
		return name;
	}

	String getId()
	{
		return id;
	}

	List<BankTab> getTabs()
	{
		return tabs;
	}

	boolean isCollapsed()
	{
		return collapsed;
	}
}

package com.expandedbanktagsviewer;

final class BankTab
{
	private final String tag;
	private final int iconItemId;

	BankTab(String tag, int iconItemId)
	{
		this.tag = tag;
		this.iconItemId = iconItemId;
	}

	String getTag()
	{
		return tag;
	}

	int getIconItemId()
	{
		return iconItemId;
	}
}

package com.expandedbanktagsviewer;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.widgets.Widget;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Resolves expanded-view tab/group drops without changing Bank Tags sidebar order. */
@Singleton
final class DragDropController
{
	private static final Logger log = LoggerFactory.getLogger(DragDropController.class);
	private final Client client;
	private final BankTabGroupManager groupManager;

	@Inject
	DragDropController(Client client, BankTabGroupManager groupManager)
	{
		this.client = client;
		this.groupManager = groupManager;
	}

	void handle(WidgetDrag event, boolean visible, ExpandedWidgetRegistry registry,
		Widget parent, int scrollOffset, ExpandedScrollbarController scrollbar, Runnable rebuild)
	{
		if (!visible)
		{
			log.debug("Ignoring WidgetDrag because expanded view is hidden");
			return;
		}

		Widget dragged = client.getDraggedWidget();
		Widget target = client.getDraggedOnWidget();
		if (client.getMouseCurrentButton() != 0)
		{
			return;
		}
		if (dragged == null)
		{
			log.debug("Ignoring released WidgetDrag because no source widget is available");
			return;
		}
		if (scrollbar.handleDrag(dragged))
		{
			log.debug("WidgetDrag was handled by the expanded scrollbar");
			return;
		}

		ExpandedWidgetRegistry.DropTarget dropTarget = registry.findDropTarget(target,
			client.getMouseCanvasPosition(), parent == null ? null : parent.getBounds(), scrollOffset,
			groupManager::getGroupId);
		log.debug("Resolved drop: source={}, targetWidget={}, matched={}, targetGroup={}, targetTab={}, scrollOffset={}",
			widgetIdentity(dragged), widgetIdentity(target), dropTarget.isMatched(),
			dropTarget.getGroupId(), dropTarget.getTabTag(), scrollOffset);
		Widget sourceGroupWidget = registry.findGroupHeader(dragged);
		if (sourceGroupWidget != null && dropTarget.isMatched())
		{
			String sourceGroupId = registry.getGroupHeaderId(sourceGroupWidget);
			log.debug("Applying group drop: sourceGroup={} destinationGroup={}",
				sourceGroupId, dropTarget.getGroupId());
			groupManager.move(sourceGroupId, dropTarget.getGroupId());
			client.setDraggedOnWidget(null);
			rebuild.run();
			return;
		}

		String tag = registry.findTab(dragged);
		if (tag == null || !dropTarget.isMatched())
		{
			log.debug("Drop produced no tab mutation: sourceTag={}, matched={}",
				tag, dropTarget.isMatched());
			return;
		}

		boolean changed = false;
		if (dropTarget.getTabTag() != null)
		{
			log.debug("Moving tab '{}' relative to tab '{}'", tag, dropTarget.getTabTag());
			changed = groupManager.moveTab(tag, dropTarget.getTabTag());
		}
		else
		{
			String destination = dropTarget.getGroupId();
			if (!equalsNullable(groupManager.getGroupId(tag), destination))
			{
				log.debug("Assigning tab '{}' to group {}", tag, destination);
				groupManager.assign(tag, destination);
				changed = true;
			}
		}
		client.setDraggedOnWidget(null);
		if (changed)
		{
			log.debug("Tab drop changed persisted order; requesting post-drag render");
			rebuild.run();
		}
		else
		{
			log.debug("Tab drop was a no-op; no render requested");
		}
	}

	private static String widgetIdentity(Widget widget)
	{
		return widget == null ? "null"
			: widget.getId() + "@" + Integer.toHexString(System.identityHashCode(widget));
	}

	private static boolean equalsNullable(Object first, Object second)
	{
		return first == null ? second == null : first.equals(second);
	}
}

package com.expandedbanktagsviewer;

import java.awt.Color;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Constants;
import net.runelite.api.FontID;
import net.runelite.api.ScriptEvent;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.banktags.tabs.TabSprites;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Creates one complete generation of expanded-view widgets. */
@Singleton
final class ExpandedViewRenderer
{
	private static final Logger log = LoggerFactory.getLogger(ExpandedViewRenderer.class);
	static final int MENU_VIEW = 1;
	static final int MENU_CHANGE_ICON = 2;
	static final int MENU_LAYOUT = 3;
	static final int MENU_EXPORT = 4;
	static final int MENU_RENAME = 5;
	static final int MENU_DELETE = 6;
	static final int GROUP_MENU_RENAME = 1;
	static final int GROUP_MENU_DELETE = 2;
	static final int GROUP_MENU_COLLAPSE = 3;

	static final String CHANGE_ICON = "Change icon";

	private static final String VIEW_TAB = "View tag tab";
	private static final String ENABLE_LAYOUT = "Enable layout";
	private static final String DISABLE_LAYOUT = "Disable layout";
	private static final String EXPORT_TAB = "Export tag tab";
	private static final String RENAME_TAB = "Rename tag tab";
	private static final String DELETE_TAB = "Delete tag tab";
	private static final String NEW_TAB = "New tag tab";
	private static final String CREATE_GROUP = "+ Create group";
	private static final String RENAME_GROUP = "Rename bank tab group";
	private static final String DELETE_GROUP = "Delete bank tab group";
	private static final String COLLAPSE_GROUP = "Collapse bank tab group";
	private static final String EXPAND_GROUP = "Expand bank tab group";

	private final BankTagsAdapter bankTags;
	private final BankTabGroupManager groupManager;

	@Inject
	ExpandedViewRenderer(BankTagsAdapter bankTags, BankTabGroupManager groupManager)
	{
		this.bankTags = bankTags;
		this.groupManager = groupManager;
	}

	RenderResult render(Widget layer, Widget bankContent, List<ExpandedViewGroup> groups,
		ExpandedWidgetRegistry registry, Listener listener)
	{
		int panelX = ExpandedViewLayout.panelX();
		int width = ExpandedViewLayout.panelWidth(bankContent.getWidth());
		log.debug("Rendering expanded widgets: layer={}, bankSize={}x{}, panelX={}, panelWidth={}, groups={}",
			widgetIdentity(layer), bankContent.getWidth(), bankContent.getHeight(), panelX, width, groups.size());
		Widget panel = layer.createChild(-1, WidgetType.RECTANGLE);
		panel.setOriginalX(panelX);
		panel.setOriginalY(ExpandedViewLayout.PANEL_TOP);
		panel.setOriginalWidth(width);
		panel.setOriginalHeight(ExpandedViewLayout.panelHeight(bankContent.getHeight()));
		panel.setFilled(false);
		panel.setOpacity(255);
		panel.setNoClickThrough(true);
		panel.setNoScrollThrough(true);
		panel.setHasListener(true);
		panel.setOnOpListener((JavaScriptCallback) event -> { });
		panel.setOnScrollWheelListener((JavaScriptCallback) event -> listener.onScroll(event.getMouseY()));
		panel.revalidate();
		registry.registerOwned(panel);

		int y = ExpandedViewLayout.firstGroupY();
		boolean renderedGroup = false;
		for (ExpandedViewGroup group : groups)
		{
			log.trace("Rendering group: id={}, name='{}', tabs={}, collapsed={}, y={}",
				group.getId(), group.getName(), group.getTabs().size(), group.isCollapsed(), y);
			if (renderedGroup)
			{
				y += ExpandedViewLayout.GROUP_SPACING;
			}
			y = renderGroup(layer, group, panelX, width, y, registry, listener);
			renderedGroup = true;
		}

		int createY = y + 8;
		Widget createGroup = createText(layer, CREATE_GROUP, panelX + 10, createY,
			Math.max(1, width - 20), 26, JagexColors.MENU_TARGET);
		createGroup.setFontId(FontID.BOLD_12);
		createGroup.setXTextAlignment(WidgetTextAlignment.CENTER);
		createGroup.setYTextAlignment(WidgetTextAlignment.CENTER);
		createGroup.setAction(1, CREATE_GROUP);
		createGroup.setHasListener(true);
		createGroup.setNoClickThrough(true);
		createGroup.setOnOpListener((JavaScriptCallback) event -> listener.onCreateGroup());
		registerScrollable(createGroup, createY, registry, listener);
		createGroup.revalidate();
		int contentBottom = createY + createGroup.getOriginalHeight();
		log.debug("Expanded widget render complete: panel={}, contentBottom={}, trackedWidgets={}",
			widgetIdentity(panel), contentBottom, registry.getOwnedWidgetCount());
		return new RenderResult(panel, contentBottom);
	}

	private int renderGroup(Widget layer, ExpandedViewGroup viewGroup, int panelX, int width, int y,
		ExpandedWidgetRegistry registry, Listener listener)
	{
		String groupId = viewGroup.getId();
		int groupTop = y;
		Widget header = createText(layer, viewGroup.getName(), panelX + 10, y, Math.max(1, width - 20),
			ExpandedViewLayout.GROUP_HEADER_HEIGHT, JagexColors.DARK_ORANGE_INTERFACE_TEXT);
		header.setFontId(FontID.BOLD_12);
		header.setXTextAlignment(WidgetTextAlignment.CENTER);
		header.setYTextAlignment(WidgetTextAlignment.CENTER);
		registry.registerGroupDropTarget(header, groupId);
		registry.registerGroupHeader(header, groupId);
		addDragOptions(header);
		header.setHasListener(true);
		if (groupId != null)
		{
			BankTabGroup group = groupManager.find(groupId);
			header.setAction(GROUP_MENU_RENAME, RENAME_GROUP);
			header.setAction(GROUP_MENU_DELETE, DELETE_GROUP);
			header.setAction(GROUP_MENU_COLLAPSE,
				group != null && group.isCollapsed() ? EXPAND_GROUP : COLLAPSE_GROUP);
			header.setNoClickThrough(true);
			header.setOnOpListener((JavaScriptCallback) listener::onGroupOperation);
		}
		header.revalidate();
		registerScrollable(header, y, registry, listener);
		y += ExpandedViewLayout.GROUP_HEADER_HEIGHT + 4;

		if (viewGroup.isCollapsed())
		{
			registry.registerGroupDropArea(groupId, panelX, width, groupTop, y);
			return y;
		}

		int startX = ExpandedViewLayout.contentStartX(panelX);
		int columns = ExpandedViewLayout.columns(width);
		List<BankTab> tabs = viewGroup.getTabs();
		for (int i = 0; i < tabs.size(); ++i)
		{
			createTabTile(layer, tabs.get(i), groupId,
				ExpandedViewLayout.tileX(startX, i, columns),
				ExpandedViewLayout.tileY(y, i, columns), registry, listener);
		}

		int addIndex = tabs.size();
		createAddTabTile(layer, groupId,
			ExpandedViewLayout.tileX(startX, addIndex, columns),
			ExpandedViewLayout.tileY(y, addIndex, columns), registry, listener);
		int groupBottom = ExpandedViewLayout.groupBottom(y, addIndex + 1, columns);
		registry.registerGroupDropArea(groupId, panelX, width, groupTop, groupBottom);
		return groupBottom;
	}

	private void createTabTile(Widget layer, BankTab tab, String groupId, int x, int y,
		ExpandedWidgetRegistry registry, Listener listener)
	{
		String target = ColorUtil.wrapWithColorTag(tab.getTag(), JagexColors.MENU_TARGET);
		int backgroundSprite = tab.getTag().equals(bankTags.getActiveTag())
			? TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId() : TabSprites.TAB_BACKGROUND.getSpriteId();
		Widget background = createGraphic(layer, target, backgroundSprite, -1,
			ExpandedViewLayout.TILE_WIDTH, ExpandedViewLayout.TILE_HEIGHT, x, y);
		addTabActions(background, tab.getTag(), listener);
		addDragOptions(background);
		registry.registerTab(background, tab.getTag());
		registry.registerGroupDropTarget(background, groupId);
		registerScrollable(background, y, registry, listener);

		Widget icon = createGraphic(layer, target, -1, tab.getIconItemId(),
			Constants.ITEM_SPRITE_WIDTH, Constants.ITEM_SPRITE_HEIGHT, x + 3, y + 4);
		registry.registerTab(icon, tab.getTag());
		icon.setClickMask(0);
		icon.setNoClickThrough(false);
		registerScrollable(icon, y + 4, registry, listener);

		background.setOnMouseOverListener((JavaScriptCallback) event ->
		{
			background.setSpriteId(TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId());
			background.revalidate();
		});
		background.setOnMouseLeaveListener((JavaScriptCallback) event ->
		{
			background.setSpriteId(tab.getTag().equals(bankTags.getActiveTag())
				? TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId() : TabSprites.TAB_BACKGROUND.getSpriteId());
			background.revalidate();
		});
	}

	private void createAddTabTile(Widget layer, String groupId, int x, int y,
		ExpandedWidgetRegistry registry, Listener listener)
	{
		Widget addTab = createGraphic(layer, "", TabSprites.NEW_TAB.getSpriteId(), -1,
			ExpandedViewLayout.TILE_WIDTH, ExpandedViewLayout.TILE_HEIGHT, x, y);
		addTab.setAction(1, NEW_TAB);
		addTab.setHasListener(true);
		addTab.setNoClickThrough(true);
		addTab.setOnOpListener((JavaScriptCallback) event -> listener.onCreateTab(groupId));
		registry.registerGroupDropTarget(addTab, groupId);
		registerScrollable(addTab, y, registry, listener);
		addTab.revalidate();
	}

	private void addTabActions(Widget widget, String tag, Listener listener)
	{
		widget.setAction(MENU_VIEW, VIEW_TAB);
		widget.setAction(MENU_CHANGE_ICON, CHANGE_ICON);
		widget.setAction(MENU_LAYOUT, bankTags.hasLayout(tag) ? DISABLE_LAYOUT : ENABLE_LAYOUT);
		widget.setAction(MENU_EXPORT, EXPORT_TAB);
		widget.setAction(MENU_RENAME, RENAME_TAB);
		widget.setAction(MENU_DELETE, DELETE_TAB);
		widget.setHasListener(true);
		widget.setOnOpListener((JavaScriptCallback) event -> listener.onTabOperation(event, tag));
	}

	private static void addDragOptions(Widget widget)
	{
		widget.setClickMask(widget.getClickMask() | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
		widget.setDragDeadTime(5);
		widget.setDragDeadZone(5);
		widget.setItemQuantity(10000);
		widget.setItemQuantityMode(ItemQuantityMode.NEVER);
	}

	private static Widget createGraphic(Widget layer, String name, int spriteId, int itemId,
		int width, int height, int x, int y)
	{
		Widget widget = layer.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalWidth(width);
		widget.setOriginalHeight(height);
		widget.setSpriteId(spriteId);
		if (itemId > -1)
		{
			widget.setItemId(itemId);
			widget.setItemQuantity(-1);
			widget.setBorderType(1);
		}
		widget.setName(name);
		widget.revalidate();
		return widget;
	}

	private static Widget createText(Widget layer, String text, int x, int y, int width, int height, Color color)
	{
		Widget widget = layer.createChild(-1, WidgetType.TEXT);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalWidth(width);
		widget.setOriginalHeight(height);
		widget.setFontId(FontID.PLAIN_11);
		widget.setText(text);
		widget.setTextColor(color.getRGB() & 0xFFFFFF);
		widget.setTextShadowed(true);
		widget.setXTextAlignment(WidgetTextAlignment.LEFT);
		widget.setYTextAlignment(WidgetTextAlignment.CENTER);
		return widget;
	}

	private static void registerScrollable(Widget widget, int baseY,
		ExpandedWidgetRegistry registry, Listener listener)
	{
		registry.registerScrollable(widget, baseY);
		widget.setOnScrollWheelListener((JavaScriptCallback) event -> listener.onScroll(event.getMouseY()));
	}

	private static String widgetIdentity(Widget widget)
	{
		return widget == null ? "null"
			: widget.getId() + "@" + Integer.toHexString(System.identityHashCode(widget));
	}

	interface Listener
	{
		void onScroll(int direction);
		void onCreateGroup();
		void onCreateTab(String groupId);
		void onTabOperation(ScriptEvent event, String tag);
		void onGroupOperation(ScriptEvent event);
	}

	static final class RenderResult
	{
		private final Widget panel;
		private final int contentBottom;

		private RenderResult(Widget panel, int contentBottom)
		{
			this.panel = panel;
			this.contentBottom = contentBottom;
		}

		Widget getPanel()
		{
			return panel;
		}

		int getContentBottom()
		{
			return contentBottom;
		}
	}
}

package com.expandedbanktagsviewer;

import java.util.ArrayList;
import java.util.List;

final class BankTabGroup
{
	private String id;
	private String name;
	private List<String> tabs = new ArrayList<>();
	private boolean collapsed;

	BankTabGroup()
	{
	}

	BankTabGroup(String id, String name)
	{
		this.id = id;
		this.name = name;
	}

	String getId()
	{
		return id;
	}

	String getName()
	{
		return name;
	}

	void setName(String name)
	{
		this.name = name;
	}

	List<String> getTabs()
	{
		return tabs;
	}

	void setTabs(List<String> tabs)
	{
		this.tabs = tabs == null ? new ArrayList<>() : tabs;
	}

	boolean isCollapsed()
	{
		return collapsed;
	}

	void setCollapsed(boolean collapsed)
	{
		this.collapsed = collapsed;
	}
}

package com.expandedbanktagsviewer;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
final class BankTabGroupManager
{
	private static final Logger log = LoggerFactory.getLogger(BankTabGroupManager.class);
	private static final String CONFIG_GROUP = "expandedbanktabs";
	private static final String CONFIG_KEY = "groups";
	private static final String LEGACY_CONFIG_GROUP = "banktags";
	private static final String LEGACY_CONFIG_KEY = "expandedGroups";
	private static final int STORAGE_VERSION = 3;

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<BankTabGroup> groups = new ArrayList<>();
	private final List<String> ungroupedTabs = new ArrayList<>();
	private int ungroupedIndex;

	@Inject
	BankTabGroupManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	void reload()
	{
		log.debug("Reloading expanded bank-tab groups from configuration");
		groups.clear();
		ungroupedTabs.clear();
		ungroupedIndex = 0;
		String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
		if (json == null || json.isEmpty())
		{
			// Preserve groups made with the earlier source-fork implementation.
			json = configManager.getConfiguration(LEGACY_CONFIG_GROUP, LEGACY_CONFIG_KEY);
		}

		if (json == null || json.isEmpty())
		{
			log.debug("No expanded group configuration was found");
			return;
		}

		try
		{
			Storage storage = gson.fromJson(json, Storage.class);
			if (storage == null || (storage.version != 1 && storage.version != 2 && storage.version != STORAGE_VERSION)
				|| storage.groups == null)
			{
				return;
			}

			Set<String> assigned = new HashSet<>();
			for (BankTabGroup group : storage.groups)
			{
				if (group == null || isBlank(group.getId()) || isBlank(group.getName()))
				{
					continue;
				}

				List<String> tabs = new ArrayList<>();
				List<String> storedTabs = group.getTabs() == null ? Collections.emptyList() : group.getTabs();
				for (String tab : storedTabs)
				{
					String normalized = normalize(tab);
					if (normalized != null && assigned.add(normalized))
					{
						tabs.add(normalized);
					}
				}
				group.setTabs(tabs);
				groups.add(group);
			}

			if (storage.version == STORAGE_VERSION && storage.ungroupedTabs != null)
			{
				for (String tab : storage.ungroupedTabs)
				{
					String normalized = normalize(tab);
					if (normalized != null && !assigned.contains(normalized) && !ungroupedTabs.contains(normalized))
					{
						ungroupedTabs.add(normalized);
					}
				}
			}

			ungroupedIndex = storage.version == STORAGE_VERSION && storage.ungroupedIndex != null
				? storage.ungroupedIndex : groups.size();
			ungroupedIndex = Math.max(0, Math.min(groups.size(), ungroupedIndex));
			log.debug("Loaded {} groups, {} explicitly ordered ungrouped tabs, ungroupedIndex={}",
				groups.size(), ungroupedTabs.size(), ungroupedIndex);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			log.warn("Unable to parse expanded bank-tab groups", ex);
			groups.clear();
		}
	}

	List<BankTabGroup> getGroups()
	{
		return Collections.unmodifiableList(groups);
	}

	BankTabGroup find(String id)
	{
		return groups.stream().filter(group -> group.getId().equals(id)).findFirst().orElse(null);
	}

	BankTabGroup create(String name)
	{
		String trimmed = name == null ? "" : name.trim();
		if (trimmed.isEmpty() || hasName(trimmed, null))
		{
			return null;
		}

		int oldSize = groups.size();
		BankTabGroup group = new BankTabGroup(UUID.randomUUID().toString(), trimmed);
		groups.add(group);
		if (ungroupedIndex == oldSize)
		{
			// Keep the default section at the bottom when a new custom group is
			// created while it is currently last.
			ungroupedIndex++;
		}
		save();
		return group;
	}

	boolean rename(String id, String name)
	{
		BankTabGroup group = find(id);
		String trimmed = name == null ? "" : name.trim();
		if (group == null || trimmed.isEmpty() || hasName(trimmed, id))
		{
			return false;
		}

		group.setName(trimmed);
		save();
		return true;
	}

	boolean delete(String id)
	{
		BankTabGroup group = find(id);
		if (group == null)
		{
			return false;
		}

		int removedIndex = groups.indexOf(group);
		groups.remove(group);
		if (removedIndex < ungroupedIndex)
		{
			ungroupedIndex--;
		}
		save();
		return true;
	}

	void toggleCollapsed(String id)
	{
		BankTabGroup group = find(id);
		if (group != null)
		{
			group.setCollapsed(!group.isCollapsed());
			save();
		}
	}

	void assign(String tag, String groupId)
	{
		String normalized = normalize(tag);
		if (normalized == null)
		{
			log.debug("Ignoring assignment for blank tab name");
			return;
		}
		log.debug("Assigning normalized tab '{}' to group {}", normalized, groupId);

		for (BankTabGroup group : groups)
		{
			group.getTabs().removeIf(tab -> normalized.equals(normalize(tab)));
		}
		ungroupedTabs.removeIf(tab -> normalized.equals(normalize(tab)));

		if (groupId != null)
		{
			BankTabGroup target = find(groupId);
			if (target != null)
			{
				target.getTabs().add(normalized);
			}
		}
		else
		{
			ungroupedTabs.add(normalized);
		}
		save();
	}

	boolean moveTab(String sourceTag, String targetTag)
	{
		String source = normalize(sourceTag);
		String target = normalize(targetTag);
		if (source == null || target == null || source.equals(target))
		{
			log.debug("Ignoring invalid tab move: source='{}', target='{}'", source, target);
			return false;
		}

		String targetGroupId = getGroupId(target);
		BankTabGroup targetGroup = targetGroupId == null ? null : find(targetGroupId);
		if (targetGroupId != null && targetGroup == null)
		{
			return false;
		}
		String sourceGroupId = getGroupId(source);
		log.debug("Moving tab '{}' from group {} relative to '{}' in group {}",
			source, sourceGroupId, target, targetGroupId);
		if (equalsNullable(sourceGroupId, targetGroupId))
		{
			if (targetGroup == null)
			{
				if (!ungroupedTabs.contains(source))
				{
					ungroupedTabs.add(source);
				}
				if (!ungroupedTabs.contains(target))
				{
					ungroupedTabs.add(target);
				}
				swap(ungroupedTabs, source, target);
			}
			else
			{
				swap(targetGroup.getTabs(), source, target);
			}
			save();
			return true;
		}

		removeFromGroups(source);
		if (targetGroupId == null)
		{
			if (!ungroupedTabs.contains(target))
			{
				ungroupedTabs.add(target);
			}
			insertBefore(ungroupedTabs, source, target);
		}
		else
		{
			int targetIndex = targetGroup.getTabs().indexOf(target);
			if (targetIndex < 0)
			{
				targetGroup.getTabs().add(source);
			}
			else
			{
				targetGroup.getTabs().add(targetIndex, source);
			}
		}
		save();
		return true;
	}

	List<String> orderUngrouped(List<String> availableTags)
	{
		Set<String> available = new HashSet<>();
		for (String tag : availableTags)
		{
			String normalized = normalize(tag);
			if (normalized != null)
			{
				available.add(normalized);
			}
		}

		Set<String> ordered = new LinkedHashSet<>();
		for (String tag : ungroupedTabs)
		{
			if (available.contains(tag))
			{
				ordered.add(tag);
			}
		}
		for (String tag : availableTags)
		{
			String normalized = normalize(tag);
			if (normalized != null)
			{
				ordered.add(normalized);
			}
		}
		return new ArrayList<>(ordered);
	}

	String getGroupId(String tag)
	{
		String normalized = normalize(tag);
		if (normalized == null)
		{
			return null;
		}

		for (BankTabGroup group : groups)
		{
			if (group.getTabs().stream().anyMatch(tab -> normalized.equals(normalize(tab))))
			{
				return group.getId();
			}
		}
		return null;
	}

	void move(String sourceId, String destinationId)
	{
		log.debug("Moving group {} relative to group {}", sourceId, destinationId);
		if (sourceId == null && destinationId == null)
		{
			return;
		}

		List<String> order = new ArrayList<>();
		for (int i = 0; i <= groups.size(); ++i)
		{
			if (i == ungroupedIndex)
			{
				order.add(null);
			}
			if (i < groups.size())
			{
				order.add(groups.get(i).getId());
			}
		}

		int sourceIndex = indexOfGroup(order, sourceId);
		int destinationIndex = indexOfGroup(order, destinationId);
		if (sourceIndex < 0 || destinationIndex < 0 || sourceIndex == destinationIndex)
		{
			log.debug("Group move is a no-op: sourceIndex={}, destinationIndex={}",
				sourceIndex, destinationIndex);
			return;
		}

		// Dropping one group header onto another swaps their positions. This is
		// predictable when the target is above or below the source and also works
		// when either side is the default ungrouped section.
		String source = order.get(sourceIndex);
		String destination = order.get(destinationIndex);
		order.set(sourceIndex, destination);
		order.set(destinationIndex, source);

		List<BankTabGroup> current = new ArrayList<>(groups);
		List<BankTabGroup> reordered = new ArrayList<>();
		int newUngroupedIndex = -1;
		for (String id : order)
		{
			if (id == null)
			{
				newUngroupedIndex = reordered.size();
				continue;
			}
			for (BankTabGroup group : current)
			{
				if (id.equals(group.getId()))
				{
					reordered.add(group);
					break;
				}
			}
		}
		if (newUngroupedIndex < 0)
		{
			return;
		}
		groups.clear();
		groups.addAll(reordered);
		ungroupedIndex = newUngroupedIndex;
		save();
	}

	int getUngroupedIndex()
	{
		return Math.max(0, Math.min(groups.size(), ungroupedIndex));
	}

	void renameTab(String oldTag, String newTag)
	{
		String oldValue = normalize(oldTag);
		String newValue = normalize(newTag);
		if (oldValue == null || newValue == null || oldValue.equals(newValue))
		{
			return;
		}

		for (BankTabGroup group : groups)
		{
			for (int i = 0; i < group.getTabs().size(); ++i)
			{
				if (oldValue.equals(normalize(group.getTabs().get(i))))
				{
					group.getTabs().set(i, newValue);
				}
			}
		}
		for (int i = 0; i < ungroupedTabs.size(); ++i)
		{
			if (oldValue.equals(normalize(ungroupedTabs.get(i))))
			{
				ungroupedTabs.set(i, newValue);
			}
		}
		save();
	}

	void removeTab(String tag)
	{
		String normalized = normalize(tag);
		if (normalized == null)
		{
			return;
		}
		for (BankTabGroup group : groups)
		{
			group.getTabs().removeIf(tab -> normalized.equals(normalize(tab)));
		}
		ungroupedTabs.removeIf(tab -> normalized.equals(normalize(tab)));
		save();
	}

	private void removeFromGroups(String tag)
	{
		for (BankTabGroup group : groups)
		{
			group.getTabs().removeIf(tab -> tag.equals(normalize(tab)));
		}
		ungroupedTabs.removeIf(tab -> tag.equals(normalize(tab)));
	}

	private static void insertBefore(List<String> values, String source, String target)
	{
		values.removeIf(source::equals);
		int targetIndex = values.indexOf(target);
		if (targetIndex < 0)
		{
			values.add(source);
		}
		else
		{
			values.add(targetIndex, source);
		}
	}

	private static void swap(List<String> values, String first, String second)
	{
		int firstIndex = values.indexOf(first);
		int secondIndex = values.indexOf(second);
		if (firstIndex >= 0 && secondIndex >= 0 && firstIndex != secondIndex)
		{
			values.set(firstIndex, second);
			values.set(secondIndex, first);
		}
	}

	private static boolean equalsNullable(String first, String second)
	{
		return first == null ? second == null : first.equals(second);
	}

	private boolean hasName(String name, String ignoredId)
	{
		return groups.stream().anyMatch(group -> !group.getId().equals(ignoredId)
			&& group.getName().equalsIgnoreCase(name));
	}

	private void save()
	{
		Storage storage = new Storage();
		storage.groups = groups;
		storage.ungroupedTabs = new ArrayList<>(ungroupedTabs);
		storage.ungroupedIndex = ungroupedIndex;
		String json = gson.toJson(storage);
		log.debug("Persisting expanded groups: groups={}, ungroupedTabs={}, ungroupedIndex={}, bytes={}",
			groups.size(), ungroupedTabs.size(), ungroupedIndex, json.length());
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, json);
	}

	private static int indexOfGroup(List<String> order, String groupId)
	{
		for (int i = 0; i < order.size(); ++i)
		{
			if (groupId == null ? order.get(i) == null : groupId.equals(order.get(i)))
			{
				return i;
			}
		}
		return -1;
	}

	private static String normalize(String value)
	{
		return isBlank(value) ? null : Text.standardize(value.trim());
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static final class Storage
	{
		private int version = STORAGE_VERSION;
		private List<BankTabGroup> groups = new ArrayList<>();
		private List<String> ungroupedTabs = new ArrayList<>();
		private Integer ungroupedIndex;
	}
}

package com.expandedbanktagsviewer;

import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Owns bank-interface state that must be restored at the end of a session. */
@Singleton
final class ExpandedWidgetSession
{
	private static final Logger log = LoggerFactory.getLogger(ExpandedWidgetSession.class);
	private final Client client;
	private final Map<Widget, Boolean> hiddenBankItems = new IdentityHashMap<>();
	private Widget layer;
	private Widget layerParent;
	private String previousTitle;

	@Inject
	ExpandedWidgetSession(Client client)
	{
		this.client = client;
	}

	boolean ensureLayer(Widget bankContent, Widget requestedParent, boolean visible, boolean enabled,
		Runnable onLayerReplaced)
	{
		if (!visible || !enabled || bankContent == null || requestedParent == null)
		{
			log.debug("Cannot ensure render layer: visible={}, enabled={}, bankContent={}, requestedParent={}",
				visible, enabled, widgetIdentity(bankContent), widgetIdentity(requestedParent));
			return false;
		}

		Widget[] children = layerParent == null ? null : layerParent.getChildren();
		boolean attached = layer != null && layerParent == requestedParent && children != null
			&& Arrays.stream(children).anyMatch(child -> child == layer);
		if (!attached)
		{
			log.debug("Replacing render layer: oldLayer={}, oldParent={}, requestedParent={}",
				widgetIdentity(layer), widgetIdentity(layerParent), widgetIdentity(requestedParent));
			disposeLayer();
			onLayerReplaced.run();
			layer = requestedParent.createChild(-1, WidgetType.LAYER);
			layerParent = requestedParent;
			log.debug("Created render layer {} under parent {}", widgetIdentity(layer),
				widgetIdentity(layerParent));
		}

		int x;
		int y;
		Point relative = WidgetGeometry.relativeLocation(bankContent, requestedParent);
		if (relative != null)
		{
			x = relative.getX();
			y = relative.getY();
		}
		else
		{
			Point contentLocation = bankContent.getCanvasLocation();
			Point parentLocation = requestedParent.getCanvasLocation();
			if (contentLocation == null || parentLocation == null)
			{
				log.debug("Cannot position render layer: contentLocation={}, parentLocation={}",
					contentLocation, parentLocation);
				return false;
			}
			x = contentLocation.getX() - parentLocation.getX();
			y = contentLocation.getY() - parentLocation.getY();
		}

		int width = Math.max(1, bankContent.getWidth());
		int height = Math.max(1, bankContent.getHeight());
		if (layer.getOriginalX() != x || layer.getOriginalY() != y
			|| layer.getOriginalWidth() != width || layer.getOriginalHeight() != height
			|| layer.getNoClickThrough() || layer.isHidden())
		{
			layer.setOriginalX(x);
			layer.setOriginalY(y);
			layer.setOriginalWidth(width);
			layer.setOriginalHeight(height);
			layer.setNoClickThrough(false);
			layer.setHidden(false);
			layer.revalidate();
		}
		return true;
	}

	Widget getLayer()
	{
		return layer;
	}

	void restoreLayerAfterBankTagsLayout(Widget panel, Runnable applyScroll)
	{
		if (layer == null)
		{
			return;
		}
		layer.setHidden(false);
		layer.revalidate();
		if (panel != null)
		{
			panel.setHidden(false);
			panel.revalidate();
			applyScroll.run();
		}
	}

	void hideLayer()
	{
		if (layer != null)
		{
			layer.setNoClickThrough(true);
			layer.setHidden(true);
			layer.revalidate();
		}
	}

	void clearLayerChildren()
	{
		if (layer != null)
		{
			Widget[] children = layer.getChildren();
			log.debug("Deleting {} children from render layer {}",
				children == null ? 0 : children.length, widgetIdentity(layer));
			layer.deleteAllChildren();
		}
	}

	void disposeLayer()
	{
		if (layer != null)
		{
			log.debug("Disposing render layer {} from parent {}", widgetIdentity(layer),
				widgetIdentity(layerParent));
			layer.deleteAllChildren();
			layer.setOriginalWidth(0);
			layer.setOriginalHeight(0);
			layer.setNoClickThrough(true);
			layer.setHidden(true);
			layer.revalidate();
		}
		layer = null;
		layerParent = null;
	}

	void hideBankItems()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.getChildren() == null)
		{
			return;
		}
		for (Widget child : items.getChildren())
		{
			if (child != null)
			{
				hiddenBankItems.putIfAbsent(child, child.isHidden());
				child.setHidden(true);
			}
		}
		log.trace("Tracking {} hidden bank item widgets", hiddenBankItems.size());
	}

	void restoreBankItems()
	{
		int restored = hiddenBankItems.size();
		for (Map.Entry<Widget, Boolean> entry : hiddenBankItems.entrySet())
		{
			if (entry.getKey() != null)
			{
				entry.getKey().setHidden(entry.getValue());
			}
		}
		hiddenBankItems.clear();
		if (restored > 0)
		{
			log.debug("Restored {} bank item widget visibility states", restored);
		}
	}

	void showExpandedTitle(String title)
	{
		Widget bankTitle = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (bankTitle != null)
		{
			if (previousTitle == null)
			{
				previousTitle = bankTitle.getText();
			}
			bankTitle.setText(title);
			bankTitle.revalidate();
		}
	}

	void restoreTitle()
	{
		if (previousTitle == null)
		{
			return;
		}
		Widget bankTitle = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (bankTitle != null)
		{
			bankTitle.setText(previousTitle);
			bankTitle.revalidate();
		}
		previousTitle = null;
	}

	void forgetTitle()
	{
		previousTitle = null;
	}

	void dispose()
	{
		restoreBankItems();
		restoreTitle();
		disposeLayer();
	}

	private static String widgetIdentity(Widget widget)
	{
		return widget == null ? "null"
			: widget.getId() + "@" + Integer.toHexString(System.identityHashCode(widget));
	}
}

package com.expandedbanktagsviewer;

import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;

/** Owns tab/group commands and their chatbox interactions. */
@Singleton
final class ExpandedBankTabActions
{
	private final Client client;
	private final ClientThread clientThread;
	private final BankTagsAdapter bankTags;
	private final BankTabGroupManager groupManager;
	private final ChatboxPanelManager chatboxPanelManager;
	private final ChatboxItemSearch itemSearch;
	private final BankTagsSidebarRefresher sidebarRefresher;

	@Inject
	ExpandedBankTabActions(Client client, ClientThread clientThread, BankTagsAdapter bankTags,
		BankTabGroupManager groupManager, ChatboxPanelManager chatboxPanelManager,
		ChatboxItemSearch itemSearch, BankTagsSidebarRefresher sidebarRefresher)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.bankTags = bankTags;
		this.groupManager = groupManager;
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemSearch = itemSearch;
		this.sidebarRefresher = sidebarRefresher;
	}

	void handleTabOperation(ScriptEvent event, String tag, Host host)
	{
		switch (event.getOp() - 1)
		{
			case ExpandedViewRenderer.MENU_VIEW:
				clientThread.invokeLater(() -> openTag(tag, host));
				break;
			case ExpandedViewRenderer.MENU_CHANGE_ICON:
				itemSearch.tooltipText(ExpandedViewRenderer.CHANGE_ICON + " (" + tag + ")")
					.onItemSelected(itemId -> setTabIcon(tag, itemId, host))
					.build();
				break;
			case ExpandedViewRenderer.MENU_LAYOUT:
				clientThread.invokeLater(() ->
				{
					bankTags.toggleLayout(tag);
					host.rebuildExpandedView();
				});
				break;
			case ExpandedViewRenderer.MENU_EXPORT:
				bankTags.exportTab(tag);
				break;
			case ExpandedViewRenderer.MENU_RENAME:
				renameTab(tag, host);
				break;
			case ExpandedViewRenderer.MENU_DELETE:
				clientThread.invokeLater(() ->
				{
					bankTags.deleteTab(tag);
					groupManager.removeTab(tag);
					host.rebuildExpandedView();
				});
				break;
			default:
				break;
		}
	}

	void handleGroupOperation(ScriptEvent event, String groupId, Host host)
	{
		BankTabGroup group = groupManager.find(groupId);
		if (group == null)
		{
			return;
		}

		switch (event.getOp() - 1)
		{
			case ExpandedViewRenderer.GROUP_MENU_RENAME:
				renameGroup(group, host);
				break;
			case ExpandedViewRenderer.GROUP_MENU_DELETE:
				chatboxPanelManager.openTextMenuInput("Delete bank tab group " + group.getName())
					.option("1. Delete group", () -> clientThread.invoke(() ->
					{
						groupManager.delete(group.getId());
						host.rebuildExpandedView();
					}))
					.option("2. Cancel", () -> { })
					.build();
				break;
			case ExpandedViewRenderer.GROUP_MENU_COLLAPSE:
				groupManager.toggleCollapsed(group.getId());
				clientThread.invokeLater(host::rebuildExpandedView);
				break;
			default:
				break;
		}
	}

	void createGroup(Host host)
	{
		chatboxPanelManager.openTextInput("Group name")
			.onDone((Consumer<String>) name -> clientThread.invoke(() ->
			{
				if (groupManager.create(name) != null)
				{
					host.rebuildExpandedView();
				}
			}))
			.build();
	}

	void createBankTab(String groupId, Host host)
	{
		chatboxPanelManager.openTextInput("Tag name")
			.addCharValidator(c -> "</>:".indexOf(c) == -1)
			.onDone((Consumer<String>) name -> clientThread.invoke(() -> createBankTabNow(name, groupId, host)))
			.build();
	}

	private void openTag(String tag, Host host)
	{
		host.closeExpandedView();
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
		bankTags.openTag(tag);
		client.playSoundEffect(SoundEffectID.UI_BOOP);
	}

	private void createBankTabNow(String name, String groupId, Host host)
	{
		String tag = bankTags.createTab(name);
		if (tag == null)
		{
			return;
		}
		if (groupId != null)
		{
			groupManager.assign(tag, groupId);
		}
		refreshSidebar(host);
	}

	private void renameGroup(BankTabGroup group, Host host)
	{
		chatboxPanelManager.openTextInput("Enter new name for bank tab group \"" + group.getName() + "\":")
			.onDone((Consumer<String>) name -> clientThread.invoke(() ->
			{
				if (groupManager.rename(group.getId(), name))
				{
					host.rebuildExpandedView();
				}
			}))
			.build();
	}

	private void setTabIcon(String tag, int itemId, Host host)
	{
		bankTags.setIcon(tag, itemId);
		refreshSidebar(host);
	}

	private void renameTab(String oldTag, Host host)
	{
		chatboxPanelManager.openTextInput("Enter new tag name for tag \"" + oldTag + "\":")
			.onDone((Consumer<String>) newTag -> clientThread.invoke(() ->
			{
				String newValue = bankTags.renameTab(oldTag, newTag);
				if (newValue != null)
				{
					groupManager.renameTab(oldTag, newValue);
					host.rebuildExpandedView();
				}
			}))
			.build();
	}

	private void refreshSidebar(Host host)
	{
		sidebarRefresher.refresh(host::prepareForSidebarRefresh, host::refreshPluginWidgets);
	}

	interface Host
	{
		void closeExpandedView();
		void rebuildExpandedView();
		void prepareForSidebarRefresh();
		void refreshPluginWidgets();
	}
}

package com.expandedbanktagsviewer;

import com.google.inject.Provides;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Expanded Bank Tags Viewer",
	description = "Organize existing Bank Tags tabs into an expanded, grouped view.",
	tags = {"bank", "bank tags", "bank tabs", "organization"}
)
@PluginDependency(BankTagsPlugin.class)
public class ExpandedBankTabsPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(ExpandedBankTabsPlugin.class);
	private static final String BANKTAGS_GROUP = "banktags";
	private static final String CONFIG_GROUP = "expandedbanktabs";
	private static final String BANKTAGS_TABS_KEY = "tagtabs";
	private static final String BANKTAGS_ICON_PREFIX = "icon_";
	private static final String BANKTAGS_LAYOUT_PREFIX = "layout_";
	private static final String LEGACY_GROUPS_KEY = "expandedGroups";
	private static final String GROUPS_KEY = "groups";
	private static final String ENABLED_KEY = "enabled";
	private static final String EXPANDED_VIEW_OPEN_KEY = "expandedViewOpen";
	private static final String EXPANDED_TITLE = "Expanded Bank Tags Viewer";

	private final ExpandedWidgetRegistry widgetRegistry = new ExpandedWidgetRegistry();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BankTagsAdapter bankTags;

	@Inject
	private BankTabGroupManager groupManager;

	@Inject
	private ExpandedViewModelFactory viewModelFactory;

	@Inject
	private ExpandedViewRenderer viewRenderer;

	@Inject
	private BankTagsSidebarRefresher sidebarRefresher;

	@Inject
	private ExpandedBankTabActions actions;

	@Inject
	private ToggleWidgetController toggleController;

	@Inject
	private ExpandedScrollbarController scrollbarController;

	@Inject
	private ExpandedWidgetSession widgetSession;

	@Inject
	private DragDropController dragDropController;

	@Inject
	private ExpandedBankTabsConfig config;

	private Widget parent;
	private Widget panel;
	private boolean expandedViewVisible;
	private int expandedScrollOffset;
	private int expandedContentBottom;
	private int renderedBankWidth;
	private int renderedBankHeight;
	private boolean expandedRebuildQueued;
	private boolean refreshQueued;
	private boolean postDragRebuildQueued;
	private boolean rebuildDeferralLogged;
	private int renderGeneration;
	private final ExpandedBankTabActions.Host actionsHost = new ExpandedBankTabActions.Host()
	{
		@Override
		public void closeExpandedView()
		{
			setExpandedViewVisible(false);
		}

		@Override
		public void rebuildExpandedView()
		{
			ExpandedBankTabsPlugin.this.rebuildExpandedView();
		}

		@Override
		public void prepareForSidebarRefresh()
		{
			removeOwnedWidgets();
			parent = null;
		}

		@Override
		public void refreshPluginWidgets()
		{
			refresh();
		}
	};
	private final ToggleWidgetController.Listener toggleListener = new ToggleWidgetController.Listener()
	{
		@Override
		public void toggleExpandedView()
		{
			ExpandedBankTabsPlugin.this.toggleExpandedView();
		}

		@Override
		public void createBankTab()
		{
			actions.createBankTab(null, actionsHost);
		}
	};
	private final ExpandedScrollbarController.Listener scrollbarListener = new ExpandedScrollbarController.Listener()
	{
		@Override
		public void scrollBy(int direction)
		{
			scrollExpandedView(direction);
		}

		@Override
		public int getMaxScroll()
		{
			return panel == null ? 0 : ExpandedViewLayout.maxScroll(panel.getOriginalY(),
				panel.getOriginalHeight(), expandedContentBottom);
		}

		@Override
		public void setScrollOffset(int offset)
		{
			expandedScrollOffset = offset;
			applyExpandedScroll();
		}
	};

	@Override
	protected void startUp()
	{
		log.debug("Starting Expanded Bank Tabs; enabled={}", config.enabled());
		groupManager.reload();
	}

	@Override
	protected void shutDown()
	{
		log.debug("Stopping Expanded Bank Tabs; visible={}, generation={}",
			expandedViewVisible, renderGeneration);
		sidebarRefresher.reset();
		setExpandedViewVisible(false, false);
		restoreBankItems();
		removeOwnedWidgets();
		parent = null;
	}

	@Provides
	ExpandedBankTabsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ExpandedBankTabsConfig.class);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		log.trace("Bank UI script completed: id={}, visible={}, panelPresent={}",
			event.getScriptId(), expandedViewVisible, panel != null);
		switch (event.getScriptId())
		{
			case ScriptID.BANKMAIN_INIT:
			case ScriptID.BANKMAIN_FINISHBUILDING:
			case ScriptID.BANKMAIN_SIZE_CHECK:
				requestRefresh();
				break;
			case ScriptID.BANKMAIN_POPUP_TAB_DRAW:
				// Bank Tags emits this while its sidebar is being repositioned,
				// including during sidebar scrolling. Its layout pass hides every
				// child after its own tab range, which also includes our expanded
				// widgets. Restore only those widgets synchronously so they are visible
				// again before the next frame is rendered; rebuilding here causes a
				// visible flash and can interrupt a drag.
				restoreExpandedViewAfterBankTagsLayout();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!config.enabled())
		{
			return;
		}

		Widget liveParent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (liveParent == null)
		{
			return;
		}

		if (parent != liveParent)
		{
			log.debug("Bank content parent changed on client tick; old={}, new={}",
				widgetIdentity(parent), widgetIdentity(liveParent));
			refresh();
			return;
		}

		toggleController.maintain(parent, config.enabled(), expandedViewVisible, toggleListener);
		if (expandedViewVisible && config.enabled())
		{
			// Reattaching the layer deletes the previous render generation. Keep the
			// widget that received mouse-down alive until RuneLite has resolved the
			// press as either a click or a drag.
			if (canRebuildExpandedViewNow())
			{
				ensureExpandedLayer();
			}
			if (panel == null)
			{
				log.debug("Expanded view is visible without a panel; requesting rebuild");
				requestExpandedViewRebuild();
			}
		}
		maintainScrollbar();
		scrollbarController.pollDrag();
		toggleController.pollFallbackClick();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!isViewConfigChange(event))
		{
			return;
		}

		log.debug("View config changed: group={}, key={}; reloading model",
			event.getGroup(), event.getKey());
		groupManager.reload();
		clientThread.invokeLater(() ->
		{
			refresh();
			requestExpandedViewRebuild();
		});
	}

	private static boolean isViewConfigChange(ConfigChanged event)
	{
		String group = event.getGroup();
		String key = event.getKey();
		if (BANKTAGS_GROUP.equals(group))
		{
			return key != null && (BANKTAGS_TABS_KEY.equals(key)
				|| LEGACY_GROUPS_KEY.equals(key)
				|| key.startsWith(BANKTAGS_ICON_PREFIX)
				|| key.startsWith(BANKTAGS_LAYOUT_PREFIX));
		}
		if (CONFIG_GROUP.equals(group))
		{
			return GROUPS_KEY.equals(key) || ENABLED_KEY.equals(key);
		}
		return false;
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			log.debug("Bank interface unloaded; clearing generation {}", renderGeneration);
			restoreBankItems();
			removeExpandedWidgets();
			disposeExpandedLayer();
			scrollbarController.dispose();
			toggleController.dispose();
			parent = null;
			expandedViewVisible = false;
			expandedScrollOffset = 0;
			widgetSession.forgetTitle();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		Widget widget = event.getWidget();
		if (toggleController.owns(widget))
		{
			if (toggleController.handleMenuOption(option))
			{
				event.consume();
				return;
			}
		}

		if (!expandedViewVisible)
		{
			return;
		}

		if (option.startsWith("View tab") || option.equals("View all items") || option.equals("View tag tab"))
		{
			if (widget != null && widgetRegistry.findTab(widget) != null)
			{
				// Let the expanded tab's own callback close the page and open the
				// selected Bank Tag. Closing here first destroys that callback source.
				return;
			}
			// Do not remove the dynamic layer while RuneLite is still traversing
			// the widget tree for this menu action. The next client tick is safe.
			clientThread.invokeLater(() -> setExpandedViewVisible(false));
		}
	}

	@Subscribe
	public void onWidgetDrag(WidgetDrag event)
	{
		// RuneLite emits WidgetDrag every client frame while mouse1 is held. Log
		// only the release event, which is when this plugin resolves the drop.
		if (client.getMouseCurrentButton() == 0)
		{
			log.debug("WidgetDrag released: visible={}, dragging={}, source={}, target={}",
				expandedViewVisible, client.isDraggingWidget(), widgetIdentity(client.getDraggedWidget()),
				widgetIdentity(client.getDraggedOnWidget()));
		}
		dragDropController.handle(event, expandedViewVisible, widgetRegistry, parent,
			expandedScrollOffset, scrollbarController, this::requestPostDragExpandedViewRebuild);
	}

	private void refresh()
	{
		Widget newParent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (newParent == null)
		{
			return;
		}

		if (parent != newParent)
		{
			log.debug("Refreshing against a new bank content parent; old={}, new={}",
				widgetIdentity(parent), widgetIdentity(newParent));
			restoreBankItems();
			removeOwnedWidgets();
			parent = newParent;
			if (config.enabled() && !expandedViewVisible && config.expandedViewOpen())
			{
				log.debug("Restoring expanded view from the previous bank session");
				setExpandedViewVisible(true, false);
			}
		}

		toggleController.maintain(parent, config.enabled(), expandedViewVisible, toggleListener);
		maintainScrollbar();
		if (expandedViewVisible && config.enabled())
		{
			// Bank Tags can recreate or unhide the normal bank item children during
			// its own refresh without changing our panel or bank geometry. Reassert
			// this non-structural state on every relevant UI refresh.
			hideBankItems();
			updateExpandedTitle();
			boolean panelMissing = panel == null;
			boolean geometryChanged = parent.getWidth() != renderedBankWidth
				|| parent.getHeight() != renderedBankHeight;
			if (panelMissing || geometryChanged)
			{
				log.debug("Refresh invalidated expanded view: panelMissing={}, geometryChanged={}, "
					+ "renderedSize={}x{}, currentSize={}x{}", panelMissing, geometryChanged,
					renderedBankWidth, renderedBankHeight, parent.getWidth(), parent.getHeight());
				requestExpandedViewRebuild();
			}
			else
			{
				log.trace("Refresh kept generation {}: panel present and geometry unchanged", renderGeneration);
			}
		}
		else
		{
			restoreBankItems();
			updateToggle();
		}
	}

	private void restoreExpandedViewAfterBankTagsLayout()
	{
		if (!expandedViewVisible || !config.enabled())
		{
			return;
		}
		hideBankItems();
		widgetSession.restoreLayerAfterBankTagsLayout(panel, this::applyExpandedScroll);
	}

	private void requestRefresh()
	{
		if (refreshQueued)
		{
			return;
		}
		refreshQueued = true;
		clientThread.invokeLater(() ->
		{
			refreshQueued = false;
			refresh();
		});
	}

	private boolean ensureExpandedLayer()
	{
		return widgetSession.ensureLayer(parent, toggleController.getLayerParent(), expandedViewVisible,
			config.enabled(), this::clearExpandedWidgetReferences);
	}

	private void hideExpandedLayer()
	{
		widgetSession.hideLayer();
	}

	private void disposeExpandedLayer()
	{
		widgetSession.disposeLayer();
	}

	private void maintainScrollbar()
	{
		scrollbarController.maintain(toggleController.getLayerParent(),
			expandedViewVisible && config.enabled(), scrollbarListener);
	}

	private void toggleExpandedView()
	{
		if (!config.enabled())
		{
			return;
		}
		setExpandedViewVisible(!expandedViewVisible);
		// Bank Tags may finish rebuilding its sidebar after the toggle callback
		// returns. Reapply the chest action after that rebuild as well.
		requestRefresh();
	}

	private void setExpandedViewVisible(boolean visible)
	{
		setExpandedViewVisible(visible, true);
	}

	private void setExpandedViewVisible(boolean visible, boolean rememberState)
	{
		if (visible == expandedViewVisible && (!visible || panel != null))
		{
			return;
		}

		log.debug("Expanded view visibility changing: {} -> {}", expandedViewVisible, visible);
		if (visible)
		{
			// Treat this like changing to a separate bank menu. This deselects the
			// currently active Bank Tags tab before the expanded page is shown.
			if (bankTags.getActiveTag() != null)
			{
				bankTags.closeTag();
			}

			widgetSession.showExpandedTitle(EXPANDED_TITLE);
		}
		else
		{
			restoreBankTitle();
		}

		expandedViewVisible = visible;
		if (rememberState)
		{
			configManager.setConfiguration(CONFIG_GROUP, EXPANDED_VIEW_OPEN_KEY, visible);
		}
		expandedScrollOffset = 0;
		if (visible)
		{
			rebuildExpandedView();
		}
		else
		{
			restoreBankItems();
			removeExpandedWidgets();
			hideExpandedLayer();
			scrollbarController.hide();
			updateToggle();
		}
	}

	private void rebuildExpandedView()
	{
		if (parent == null || !expandedViewVisible || !config.enabled())
		{
			log.debug("Skipping rebuild: parentPresent={}, visible={}, enabled={}",
				parent != null, expandedViewVisible, config.enabled());
			return;
		}

		int nextGeneration = renderGeneration + 1;
		log.debug("Beginning rebuild generation {}; oldPanel={}, scrollOffset={}",
			nextGeneration, widgetIdentity(panel), expandedScrollOffset);
		removeExpandedWidgets();
		if (!ensureExpandedLayer())
		{
			log.debug("Generation {} aborted because no render layer could be attached", nextGeneration);
			return;
		}

		hideBankItems();
		updateExpandedTitle();
		updateToggle();
		List<ExpandedViewGroup> viewModel = viewModelFactory.create();
		int tabCount = viewModel.stream().mapToInt(group -> group.getTabs().size()).sum();
		log.debug("Rendering generation {} with {} groups and {} tabs", nextGeneration,
			viewModel.size(), tabCount);
		ExpandedViewRenderer.RenderResult renderResult = viewRenderer.render(widgetSession.getLayer(), parent,
			viewModel, widgetRegistry, new ExpandedViewRenderer.Listener()
			{
				@Override
				public void onScroll(int direction)
				{
					scrollExpandedView(direction);
				}

				@Override
				public void onCreateGroup()
				{
					actions.createGroup(actionsHost);
				}

				@Override
				public void onCreateTab(String groupId)
				{
					actions.createBankTab(groupId, actionsHost);
				}

				@Override
				public void onTabOperation(ScriptEvent event, String tag)
				{
					actions.handleTabOperation(event, tag, actionsHost);
				}

				@Override
				public void onGroupOperation(ScriptEvent event)
				{
					actions.handleGroupOperation(event,
						widgetRegistry.getGroupHeaderId(event.getSource()), actionsHost);
				}
			});
		panel = renderResult.getPanel();
		expandedContentBottom = renderResult.getContentBottom();
		renderedBankWidth = parent.getWidth();
		renderedBankHeight = parent.getHeight();
		renderGeneration = nextGeneration;
		applyExpandedScroll();
		maintainScrollbar();
		log.debug("Completed generation {}; panel={}, contentBottom={}, trackedWidgets={}",
			renderGeneration, widgetIdentity(panel), expandedContentBottom, widgetRegistry.getOwnedWidgetCount());
	}

	private void requestExpandedViewRebuild()
	{
		if (!expandedViewVisible || !config.enabled() || expandedRebuildQueued || postDragRebuildQueued)
		{
			log.trace("Ignoring rebuild request: visible={}, enabled={}, alreadyQueued={}, postDragQueued={}",
				expandedViewVisible, config.enabled(), expandedRebuildQueued, postDragRebuildQueued);
			return;
		}

		expandedRebuildQueued = true;
		rebuildDeferralLogged = false;
		log.debug("Queued guarded rebuild after generation {}", renderGeneration);
		clientThread.invokeLater(() ->
		{
			// A completed drop can supersede this guarded request with a guaranteed
			// tick-end rebuild. Remove this queue entry once that happens.
			if (!expandedRebuildQueued)
			{
				log.debug("Removing guarded rebuild because a newer request superseded it");
				return true;
			}

			if (!expandedViewVisible || !config.enabled())
			{
				expandedRebuildQueued = false;
				return true;
			}

			// The state may have changed since this rebuild was queued. Returning
			// false keeps the same request queued for a later client cycle without
			// destroying the widget currently being considered for a drag.
			if (!canRebuildExpandedViewNow())
			{
				if (!rebuildDeferralLogged)
				{
					rebuildDeferralLogged = true;
					log.debug("Deferring rebuild: menuOpen={}, mouseButton={}, dragging={}",
						client.isMenuOpen(), client.getMouseCurrentButton(), client.isDraggingWidget());
				}
				return false;
			}

			expandedRebuildQueued = false;
			rebuildDeferralLogged = false;
			log.debug("Executing guarded rebuild after generation {}", renderGeneration);
			rebuildExpandedView();
			return true;
		});
	}

	private void requestPostDragExpandedViewRebuild()
	{
		if (!expandedViewVisible || !config.enabled() || postDragRebuildQueued)
		{
			log.debug("Ignoring post-drag rebuild request: visible={}, enabled={}, alreadyQueued={}",
				expandedViewVisible, config.enabled(), postDragRebuildQueued);
			return;
		}

		postDragRebuildQueued = true;
		// The completed-drop render is authoritative and runs at tick end. Cancel
		// any older guarded request now so config-change events from the same save
		// cannot produce a second generation first.
		expandedRebuildQueued = false;
		rebuildDeferralLogged = false;
		log.debug("Queued tick-end rebuild for completed drag after generation {}", renderGeneration);
		clientThread.invokeAtTickEnd(() ->
		{
			log.debug("Executing completed-drag callback: visible={}, enabled={}, generation={}",
				expandedViewVisible, config.enabled(), renderGeneration);
			postDragRebuildQueued = false;
			// Cancel any older guarded request. Its queued callback will observe the
			// cleared flag and remove itself without producing a duplicate render.
			expandedRebuildQueued = false;
			if (expandedViewVisible && config.enabled())
			{
				rebuildExpandedView();
			}
		});
	}

	private boolean canRebuildExpandedViewNow()
	{
		return !client.isMenuOpen()
			&& client.getMouseCurrentButton() == 0;
	}

	private void scrollExpandedView(int direction)
	{
		if (panel == null || direction == 0)
		{
			return;
		}
		int maxScroll = ExpandedViewLayout.maxScroll(panel.getOriginalY(),
			panel.getOriginalHeight(), expandedContentBottom);
		expandedScrollOffset = Math.max(0, Math.min(maxScroll, expandedScrollOffset + direction * 24));
		applyExpandedScroll();
	}

	private void applyExpandedScroll()
	{
		if (panel == null)
		{
			return;
		}

		// The group list now starts near the top of the panel because the create
		// control was moved below the groups. Keep that first header in the
		// viewport instead of using the old top-control padding.
		int viewportTop = panel.getOriginalY() + 8;
		int viewportBottom = panel.getOriginalY() + panel.getOriginalHeight();
		int maxScroll = ExpandedViewLayout.maxScroll(panel.getOriginalY(),
			panel.getOriginalHeight(), expandedContentBottom);
		expandedScrollOffset = Math.max(0, Math.min(maxScroll, expandedScrollOffset));
		widgetRegistry.forEachScrollable((widget, baseY) ->
		{
			int y = baseY - expandedScrollOffset;
			widget.setOriginalY(y);
			// Widgets are siblings of the panel rather than children of a clipping
			// layer, so hide them before they can partially render over the bank
			// footer or scrollbar.
			widget.setHidden(y < viewportTop || y + widget.getOriginalHeight() > viewportBottom);
			widget.revalidate();
		});
	}

	private void updateToggle()
	{
		toggleController.updateState(config.enabled(), expandedViewVisible);
	}

	private void hideBankItems()
	{
		widgetSession.hideBankItems();
	}

	private void restoreBankItems()
	{
		widgetSession.restoreBankItems();
	}

	private void removeExpandedWidgets()
	{
		log.debug("Retiring generation {} with {} tracked widgets", renderGeneration,
			widgetRegistry.getOwnedWidgetCount());
		// Retire the complete generation before asking RuneLite to remove its
		// dynamic children. This prevents deferred children from remaining visible
		// or interactive while the replacement generation is being constructed.
		widgetRegistry.retireOwnedWidgets();
		widgetSession.clearLayerChildren();
		clearExpandedWidgetReferences();
	}

	private void clearExpandedWidgetReferences()
	{
		panel = null;
		widgetRegistry.clear();
		expandedContentBottom = 0;
		renderedBankWidth = 0;
		renderedBankHeight = 0;
	}

	private void removeOwnedWidgets()
	{
		removeExpandedWidgets();
		disposeExpandedLayer();
		scrollbarController.dispose();
		toggleController.dispose();
		clearExpandedWidgetReferences();
	}

	private void restoreBankTitle()
	{
		widgetSession.restoreTitle();
	}

	private void updateExpandedTitle()
	{
		if (!expandedViewVisible)
		{
			return;
		}
		widgetSession.showExpandedTitle(EXPANDED_TITLE);
	}

	private static String widgetIdentity(Widget widget)
	{
		return widget == null ? "null"
			: widget.getId() + "@" + Integer.toHexString(System.identityHashCode(widget));
	}

}

