package com.expandedbanktagsviewer;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.Function;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Owns all widget-to-domain mappings for the current expanded-view render.
 * Clearing this registry invalidates every old drag, drop, tab, and scroll
 * mapping together so render generations cannot overlap.
 */
final class ExpandedWidgetRegistry
{
	private static final Logger log = LoggerFactory.getLogger(ExpandedWidgetRegistry.class);
	private final Map<Widget, String> tabWidgets = new IdentityHashMap<>();
	private final Map<Widget, String> groupHeaders = new IdentityHashMap<>();
	private final Map<Widget, String> groupDropTargets = new IdentityHashMap<>();
	private final Map<Widget, Integer> scrollBaseY = new IdentityHashMap<>();
	private final List<GroupDropArea> groupDropAreas = new ArrayList<>();
	private final Set<Widget> ownedWidgets = java.util.Collections.newSetFromMap(new IdentityHashMap<>());

	void registerOwned(Widget widget)
	{
		ownedWidgets.add(widget);
	}

	void registerTab(Widget widget, String tag)
	{
		registerOwned(widget);
		tabWidgets.put(widget, tag);
	}

	String findTab(Widget widget)
	{
		return findMappedAncestor(widget, tabWidgets);
	}

	void registerGroupHeader(Widget widget, String groupId)
	{
		registerOwned(widget);
		groupHeaders.put(widget, groupId);
	}

	Widget findGroupHeader(Widget widget)
	{
		return findMappedWidget(widget, groupHeaders);
	}

	String getGroupHeaderId(Widget widget)
	{
		return groupHeaders.get(widget);
	}

	void registerGroupDropTarget(Widget widget, String groupId)
	{
		registerOwned(widget);
		groupDropTargets.put(widget, groupId);
		widget.setClickMask(widget.getClickMask() | WidgetConfig.DRAG_ON);
	}

	void registerGroupDropArea(String groupId, int x, int width, int top, int bottom)
	{
		groupDropAreas.add(new GroupDropArea(groupId, x, width, top, Math.max(1, bottom - top)));
	}

	DropTarget findDropTarget(Widget target, Point mouse, Rectangle parentBounds, int scrollOffset,
		Function<String, String> groupForTab)
	{
		String tabTag = findTab(target);
		if (tabTag != null)
		{
			log.trace("Drop target resolved from widget mapping: tab='{}'", tabTag);
			return DropTarget.forTab(groupForTab.apply(tabTag), tabTag);
		}

		for (Widget current = target; current != null; current = current.getParent())
		{
			if (groupDropTargets.containsKey(current))
			{
				log.trace("Drop target resolved from group widget mapping: group={}",
					groupDropTargets.get(current));
				return DropTarget.forGroup(groupDropTargets.get(current));
			}
		}

		if (mouse == null || parentBounds == null)
		{
			log.trace("Drop target unresolved because pointer or parent bounds are unavailable");
			return DropTarget.none();
		}

		int localX = mouse.getX() - parentBounds.x;
		int localY = mouse.getY() - parentBounds.y + scrollOffset;
		for (Map.Entry<Widget, String> entry : tabWidgets.entrySet())
		{
			Rectangle bounds = entry.getKey().getBounds();
			if (bounds != null && bounds.contains(mouse.getX(), mouse.getY()))
			{
				String matchedTag = entry.getValue();
				log.trace("Drop target resolved by tab bounds fallback: tab='{}'", matchedTag);
				return DropTarget.forTab(groupForTab.apply(matchedTag), matchedTag);
			}
		}
		for (GroupDropArea area : groupDropAreas)
		{
			if (area.contains(localX, localY))
			{
				log.trace("Drop target resolved by group-area fallback: group={}, local=({}, {})",
					area.groupId, localX, localY);
				return DropTarget.forGroup(area.groupId);
			}
		}
		log.trace("No drop target matched pointer local=({}, {})", localX, localY);
		return DropTarget.none();
	}

	void registerScrollable(Widget widget, int baseY)
	{
		registerOwned(widget);
		scrollBaseY.put(widget, baseY);
	}

	void forEachScrollable(BiConsumer<Widget, Integer> consumer)
	{
		scrollBaseY.forEach(consumer);
	}

	int getOwnedWidgetCount()
	{
		return ownedWidgets.size();
	}

	void retireOwnedWidgets()
	{
		log.debug("Retiring {} owned expanded-view widgets", ownedWidgets.size());
		for (Widget widget : ownedWidgets)
		{
			if (widget != null)
			{
				widget.clearActions();
				widget.setHidden(true);
				widget.setOriginalWidth(0);
				widget.setOriginalHeight(0);
				widget.revalidate();
			}
		}
	}

	void clear()
	{
		log.trace("Clearing widget registry: tabs={}, headers={}, dropTargets={}, areas={}, scrollables={}, owned={}",
			tabWidgets.size(), groupHeaders.size(), groupDropTargets.size(), groupDropAreas.size(),
			scrollBaseY.size(), ownedWidgets.size());
		tabWidgets.clear();
		groupHeaders.clear();
		groupDropTargets.clear();
		groupDropAreas.clear();
		scrollBaseY.clear();
		ownedWidgets.clear();
	}

	private static String findMappedAncestor(Widget widget, Map<Widget, String> mappings)
	{
		for (Widget current = widget; current != null; current = current.getParent())
		{
			String value = mappings.get(current);
			if (value != null)
			{
				return value;
			}
		}
		return null;
	}

	private static Widget findMappedWidget(Widget widget, Map<Widget, String> mappings)
	{
		for (Widget current = widget; current != null; current = current.getParent())
		{
			if (mappings.containsKey(current))
			{
				return current;
			}
		}
		return null;
	}

	static final class DropTarget
	{
		private static final DropTarget NONE = new DropTarget(false, null, null);

		private final boolean matched;
		private final String groupId;
		private final String tabTag;

		private DropTarget(boolean matched, String groupId, String tabTag)
		{
			this.matched = matched;
			this.groupId = groupId;
			this.tabTag = tabTag;
		}

		static DropTarget none()
		{
			return NONE;
		}

		static DropTarget forGroup(String groupId)
		{
			return new DropTarget(true, groupId, null);
		}

		static DropTarget forTab(String groupId, String tabTag)
		{
			return new DropTarget(true, groupId, tabTag);
		}

		boolean isMatched()
		{
			return matched;
		}

		String getGroupId()
		{
			return groupId;
		}

		String getTabTag()
		{
			return tabTag;
		}
	}

	private static final class GroupDropArea
	{
		private final String groupId;
		private final int x;
		private final int width;
		private final int y;
		private final int height;

		private GroupDropArea(String groupId, int x, int width, int y, int height)
		{
			this.groupId = groupId;
			this.x = x;
			this.width = width;
			this.y = y;
			this.height = height;
		}

		private boolean contains(int localX, int localY)
		{
			return localX >= x && localX < x + width && localY >= y && localY < y + height;
		}
	}
}

package com.expandedbanktagsviewer;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Coordinates the Bank Tags plugin lifecycle when its persisted tab list changes. */
@Singleton
final class BankTagsSidebarRefresher
{
	private static final Logger log = LoggerFactory.getLogger(BankTagsSidebarRefresher.class);

	private final ClientThread clientThread;
	private final BankTagsPlugin bankTagsPlugin;
	private final PluginManager pluginManager;
	private boolean pending;
	private int generation;

	@Inject
	BankTagsSidebarRefresher(ClientThread clientThread, BankTagsPlugin bankTagsPlugin,
		PluginManager pluginManager)
	{
		this.clientThread = clientThread;
		this.bankTagsPlugin = bankTagsPlugin;
		this.pluginManager = pluginManager;
	}

	void refresh(Runnable beforeRestart, Runnable afterRestart)
	{
		log.debug("Sidebar refresh requested: pending={}, bankTagsActive={}, generation={}",
			pending, pluginManager.isPluginActive(bankTagsPlugin), generation);
		beforeRestart.run();
		if (pending || !pluginManager.isPluginActive(bankTagsPlugin))
		{
			log.debug("Skipping Bank Tags restart; queueing plugin widget refresh only");
			clientThread.invokeLater(afterRestart);
			return;
		}

		pending = true;
		int requestGeneration = generation;
		log.debug("Scheduling Bank Tags restart for generation {}", requestGeneration);
		SwingUtilities.invokeLater(() -> restart(requestGeneration, afterRestart));
	}

	void reset()
	{
		log.debug("Resetting sidebar refresher: generation {} -> {}", generation, generation + 1);
		pending = false;
		generation++;
	}

	private void restart(int requestGeneration, Runnable afterRestart)
	{
		if (requestGeneration != generation)
		{
			log.debug("Discarding stale sidebar restart generation {}; current={}",
				requestGeneration, generation);
			return;
		}
		try
		{
			log.debug("Stopping Bank Tags for sidebar refresh generation {}", requestGeneration);
			pluginManager.stopPlugin(bankTagsPlugin);
		}
		catch (PluginInstantiationException ex)
		{
			log.warn("Unable to restart Bank Tags after changing its tabs", ex);
			finish(requestGeneration, afterRestart);
			return;
		}

		// Bank Tags deinitializes on the client thread. Queue the restart after
		// that work so its TabInterface rebuilds from the newly saved config.
		clientThread.invokeLater(() -> SwingUtilities.invokeLater(() ->
		{
			if (requestGeneration != generation)
			{
				return;
			}
			try
			{
				if (pluginManager.isPluginEnabled(bankTagsPlugin))
				{
					log.debug("Starting Bank Tags for sidebar refresh generation {}", requestGeneration);
					pluginManager.startPlugin(bankTagsPlugin);
				}
			}
			catch (PluginInstantiationException ex)
			{
				log.warn("Unable to start Bank Tags after changing its tabs", ex);
			}
			finally
			{
				finish(requestGeneration, afterRestart);
			}
		}));
	}

	private void finish(int requestGeneration, Runnable afterRestart)
	{
		if (requestGeneration != generation)
		{
			return;
		}
		pending = false;
		log.debug("Sidebar refresh generation {} finished; queueing plugin refresh", requestGeneration);
		clientThread.invokeLater(afterRestart);
	}
}

package com.expandedbanktagsviewer;

import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

final class WidgetGeometry
{
	private WidgetGeometry()
	{
	}

	static Point relativeLocation(Widget widget, Widget ancestor)
	{
		int x = 0;
		int y = 0;
		Widget current = widget;
		while (current != null && current != ancestor)
		{
			x += current.getRelativeX();
			y += current.getRelativeY();
			current = current.getParent();
		}
		return current == ancestor ? new Point(x, y) : null;
	}

	static Widget findLayerAncestor(Widget start)
	{
		for (Widget current = start; current != null; current = current.getParent())
		{
			if (current.getType() == WidgetType.LAYER)
			{
				return current;
			}
		}
		return null;
	}
}

package com.expandedbanktagsviewer;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Isolates Expanded Bank Tags Viewer from Bank Tags storage and manager details.
 * Rendering code should consume {@link BankTab} values and never read Bank Tags
 * configuration directly.
 */
@Singleton
final class BankTagsAdapter
{
	private static final String CONFIG_GROUP = "banktags";
	private static final String TABS_KEY = "tagtabs";
	private static final String ICON_PREFIX = "icon_";
	private static final String LAYOUT_PREFIX = "layout_";
	private static final String ITEM_PREFIX = "item_";

	private final ConfigManager configManager;
	private final BankTagsService bankTagsService;
	private final TabManager tabManager;

	@Inject
	BankTagsAdapter(ConfigManager configManager, BankTagsService bankTagsService, TabManager tabManager)
	{
		this.configManager = configManager;
		this.bankTagsService = bankTagsService;
		this.tabManager = tabManager;
	}

	List<BankTab> loadTabs()
	{
		String value = configManager.getConfiguration(CONFIG_GROUP, TABS_KEY);
		if (value == null || value.isEmpty())
		{
			return Collections.emptyList();
		}

		List<BankTab> tabs = new ArrayList<>();
		for (String tag : Text.fromCSV(value))
		{
			String normalized = Text.standardize(tag);
			if (!normalized.isEmpty())
			{
				tabs.add(new BankTab(normalized, iconFor(normalized)));
			}
		}
		return tabs;
	}

	String getActiveTag()
	{
		return bankTagsService == null ? null : bankTagsService.getActiveTag();
	}

	void openTag(String tag)
	{
		if (bankTagsService != null)
		{
			bankTagsService.openBankTag(tag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
	}

	void closeTag()
	{
		if (bankTagsService != null)
		{
			bankTagsService.closeBankTag();
		}
	}

	String createTab(String name)
	{
		String tag = normalize(name);
		if (tag.isEmpty() || tabManager.find(tag) != null)
		{
			return null;
		}

		TagTab newTab = new TagTab();
		newTab.setTag(tag);
		newTab.setIconItemId(ItemID.SPADE);
		tabManager.add(newTab);
		tabManager.save();
		return tag;
	}

	void setIcon(String tag, int itemId)
	{
		String normalized = normalize(tag);
		TagTab tab = tabManager.find(normalized);
		if (tab != null)
		{
			tab.setIconItemId(itemId);
			tabManager.save();
			return;
		}

		configManager.setConfiguration(CONFIG_GROUP, ICON_PREFIX + normalized, itemId);
	}

	boolean hasLayout(String tag)
	{
		return configManager.getConfiguration(CONFIG_GROUP, LAYOUT_PREFIX + normalize(tag)) != null;
	}

	void toggleLayout(String tag)
	{
		String normalized = normalize(tag);
		String key = LAYOUT_PREFIX + normalized;
		if (configManager.getConfiguration(CONFIG_GROUP, key) == null)
		{
			configManager.setConfiguration(CONFIG_GROUP, key, "");
		}
		else
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key);
		}

		if (normalized.equals(getActiveTag()))
		{
			openTag(normalized);
		}
	}

	String renameTab(String oldTag, String newTag)
	{
		String oldValue = normalize(oldTag);
		String newValue = normalize(newTag);
		if (newValue.isEmpty() || oldValue.equals(newValue)
			|| loadTabs().stream().anyMatch(tab -> tab.getTag().equals(newValue)))
		{
			return null;
		}

		List<String> tabs = loadTabs().stream().map(BankTab::getTag).collect(Collectors.toList());
		Collections.replaceAll(tabs, oldValue, newValue);
		configManager.setConfiguration(CONFIG_GROUP, TABS_KEY, Text.toCSV(tabs));
		moveConfig(ICON_PREFIX + oldValue, ICON_PREFIX + newValue);
		moveConfig(LAYOUT_PREFIX + oldValue, LAYOUT_PREFIX + newValue);
		rewriteItemTags(oldValue, newValue);
		rewriteItemTags(oldValue + "*", newValue + "*");

		if (oldValue.equals(getActiveTag()))
		{
			openTag(newValue);
		}
		return newValue;
	}

	void deleteTab(String tag)
	{
		String normalized = normalize(tag);
		List<String> tabs = loadTabs().stream().map(BankTab::getTag)
			.filter(value -> !value.equals(normalized)).collect(Collectors.toList());
		configManager.setConfiguration(CONFIG_GROUP, TABS_KEY, Text.toCSV(tabs));
		configManager.unsetConfiguration(CONFIG_GROUP, ICON_PREFIX + normalized);
		configManager.unsetConfiguration(CONFIG_GROUP, LAYOUT_PREFIX + normalized);
		rewriteItemTags(normalized, null);
		rewriteItemTags(normalized + "*", null);

		if (normalized.equals(getActiveTag()))
		{
			closeTag();
		}
	}

	void exportTab(String tag)
	{
		String normalized = normalize(tag);
		List<String> data = new ArrayList<>();
		data.add("banktags");
		data.add("1");
		data.add(normalized);
		data.add(String.valueOf(iconFor(normalized)));
		for (String key : configManager.getConfigurationKeys(CONFIG_GROUP + "." + ITEM_PREFIX))
		{
			String[] split = key.split("\\.", 2);
			if (split.length != 2)
			{
				continue;
			}
			String values = configManager.getConfiguration(CONFIG_GROUP, split[1]);
			if (values != null && Text.fromCSV(values).stream().map(Text::standardize)
				.anyMatch(normalized::equals))
			{
				data.add(split[1].substring(ITEM_PREFIX.length()));
			}
		}
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(Text.toCSV(data)), null);
	}

	private int iconFor(String tag)
	{
		String value = configManager.getConfiguration(CONFIG_GROUP, ICON_PREFIX + normalize(tag));
		try
		{
			return value == null ? ItemID.SPADE : Integer.parseInt(value);
		}
		catch (NumberFormatException ex)
		{
			return ItemID.SPADE;
		}
	}

	private void rewriteItemTags(String oldTag, String newTag)
	{
		for (String key : configManager.getConfigurationKeys(CONFIG_GROUP + "." + ITEM_PREFIX))
		{
			String[] split = key.split("\\.", 2);
			if (split.length != 2)
			{
				continue;
			}
			String stored = configManager.getConfiguration(CONFIG_GROUP, split[1]);
			if (stored == null)
			{
				continue;
			}

			List<String> tags = new ArrayList<>(Text.fromCSV(stored));
			boolean changed;
			if (newTag == null)
			{
				changed = tags.removeIf(oldTag::equals);
			}
			else
			{
				changed = Collections.replaceAll(tags, oldTag, newTag);
			}
			if (changed)
			{
				configManager.setConfiguration(CONFIG_GROUP, split[1], Text.toCSV(tags));
			}
		}
	}

	private void moveConfig(String oldKey, String newKey)
	{
		String value = configManager.getConfiguration(CONFIG_GROUP, oldKey);
		if (value != null)
		{
			configManager.setConfiguration(CONFIG_GROUP, newKey, value);
			configManager.unsetConfiguration(CONFIG_GROUP, oldKey);
		}
	}

	private static String normalize(String tag)
	{
		return tag == null ? "" : Text.standardize(tag.trim());
	}
}

package com.expandedbanktagsviewer;

/** Pure geometry calculations for the expanded bank view. */
final class ExpandedViewLayout
{
	static final int TAB_WIDTH = 39;
	static final int TAB_HEIGHT = 39;
	static final int PANEL_TOP = 41;
	static final int TILE_WIDTH = 39;
	static final int TILE_HEIGHT = 40;
	static final int GROUP_HEADER_HEIGHT = 24;
	static final int GROUP_SPACING = 8;

	private static final int BANK_BOTTOM_OFFSET = 39;
	private static final int TILE_GAP = 1;
	private static final int PANEL_LEFT_GAP = 2;
	private static final int CONTENT_INSET = 12;

	private ExpandedViewLayout()
	{
	}

	static int panelX()
	{
		return TAB_WIDTH + PANEL_LEFT_GAP;
	}

	static int panelWidth(int parentWidth)
	{
		return Math.max(1, parentWidth - panelX());
	}

	static int panelHeight(int parentHeight)
	{
		return Math.max(1, parentHeight - BANK_BOTTOM_OFFSET - PANEL_TOP);
	}

	static int firstGroupY()
	{
		return PANEL_TOP + 8;
	}

	static int contentStartX(int panelX)
	{
		return panelX + CONTENT_INSET;
	}

	static int columns(int panelWidth)
	{
		return Math.max(1, (panelWidth - CONTENT_INSET + TILE_GAP) / (TILE_WIDTH + TILE_GAP));
	}

	static int tileX(int startX, int index, int columns)
	{
		return startX + (index % columns) * (TILE_WIDTH + TILE_GAP);
	}

	static int tileY(int startY, int index, int columns)
	{
		return startY + (index / columns) * (TILE_HEIGHT + TILE_GAP);
	}

	static int groupBottom(int contentY, int tileCount, int columns)
	{
		int rows = (tileCount + columns - 1) / columns;
		return contentY + rows * (TILE_HEIGHT + TILE_GAP);
	}

	static int maxScroll(int panelY, int panelHeight, int contentBottom)
	{
		return Math.max(0, contentBottom - (panelY + panelHeight) + 8);
	}
}

package com.expandedbanktagsviewer;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Text;

/**
 * Produces a deterministic snapshot for one expanded-view render. Keeping this
 * separate from widgets prevents rendering code from mutating group storage and
 * avoids repeatedly scanning the full tab list for every group entry.
 */
@Singleton
final class ExpandedViewModelFactory
{
	private static final String UNGROUPED_NAME = "Ungrouped bank tabs (default)";

	private final BankTagsAdapter bankTags;
	private final BankTabGroupManager groupManager;

	@Inject
	ExpandedViewModelFactory(BankTagsAdapter bankTags, BankTabGroupManager groupManager)
	{
		this.bankTags = bankTags;
		this.groupManager = groupManager;
	}

	List<ExpandedViewGroup> create()
	{
		List<BankTab> allTabs = bankTags.loadTabs();
		Map<String, BankTab> tabsByTag = new HashMap<>();
		for (BankTab tab : allTabs)
		{
			tabsByTag.put(tab.getTag(), tab);
		}

		List<ExpandedViewGroup> result = new ArrayList<>();
		List<BankTabGroup> customGroups = groupManager.getGroups();
		Set<String> assignedTags = new HashSet<>();
		for (BankTabGroup group : customGroups)
		{
			for (String tag : group.getTabs())
			{
				assignedTags.add(Text.standardize(tag));
			}
		}
		int ungroupedIndex = groupManager.getUngroupedIndex();
		for (int i = 0; i <= customGroups.size(); ++i)
		{
			if (i == ungroupedIndex)
			{
				result.add(new ExpandedViewGroup(UNGROUPED_NAME, null,
					orderedUngrouped(allTabs, tabsByTag, assignedTags), false));
			}

			if (i < customGroups.size())
			{
				BankTabGroup group = customGroups.get(i);
				result.add(new ExpandedViewGroup(group.getName(), group.getId(),
					orderedTabs(group.getTabs(), tabsByTag), group.isCollapsed()));
			}
		}
		return result;
	}

	private List<BankTab> orderedUngrouped(List<BankTab> allTabs, Map<String, BankTab> tabsByTag,
		Set<String> assignedTags)
	{
		List<String> availableTags = new ArrayList<>();
		for (BankTab tab : allTabs)
		{
			if (!assignedTags.contains(tab.getTag()))
			{
				availableTags.add(tab.getTag());
			}
		}
		return orderedTabs(groupManager.orderUngrouped(availableTags), tabsByTag);
	}

	private static List<BankTab> orderedTabs(List<String> orderedTags, Map<String, BankTab> tabsByTag)
	{
		List<BankTab> result = new ArrayList<>();
		for (String tag : orderedTags)
		{
			BankTab tab = tabsByTag.get(Text.standardize(tag));
			if (tab != null)
			{
				result.add(tab);
			}
		}
		return result;
	}
}
